  "settings.sandboxProfileDesc":
    "对 Agent 进程施加操作系统级文件系统/网络隔离（Linux Landlock / macOS Seatbelt）。在新启动 Agent 时生效——更改后请重连会话。可在项目菜单中为单个项目覆盖。",
