  "settings.allowedTools": "允许的工具",
  "settings.allowedToolsDesc":
    "通过 --tools（逗号分隔）限制可用内置工具。留空 = 全部工具（CLI 默认）。设置后仅列出的工具可用。可与下方「禁用内置工具」并存（denylist 仍生效）。更改后会 soft-respawn。",
