  "settings.remoteIm.discord.tokenHelp": "来自 Discord 开发者后台（Bot → Reset Token）的 Bot Token。遮罩存储，永不写入日志。运行时亦接受 bot_token 别名。",
  "settings.remoteIm.discord.tokenPlaceholder": "MTEx….GaBc….xxxx",
  "settings.remoteIm.discord.allowFromHelp": "允许与机器人对话的 Discord 用户雪花 ID，逗号分隔；或 * 表示任意（生产环境建议写明 ID）。",
