  "settings.remoteIm.discord.progressHelp": "Agent 工作时的进度展示样式（legacy · compact · card）。",
  "settings.remoteIm.discord.guide.title": "Discord 接入",
  "settings.remoteIm.discord.guide.step1": "打开 Discord 开发者后台 → New Application → Bot → 创建机器人并复制 Token。",
  "settings.remoteIm.discord.guide.step2": "在 Bot → Privileged Gateway Intents 中开启 Message Content Intent（否则无法读取消息正文）。",
  "settings.remoteIm.discord.guide.step3": "OAuth2 → URL Generator：勾选 bot（如需斜杠命令再加 applications.commands），选择权限后邀请机器人进服。",
  "settings.remoteIm.discord.guide.step4": "将 Bot Token 粘贴到此处，设置 allow-from（生产环境避免 *），再点「保存并连接」。Gateway 无需公网 URL。",
  "settings.remoteIm.discord.guide.softFail": "「测试连接」会校验 Token 格式，并在可联网时调用 REST @me 校验机器人身份 — 不代表 Gateway 已连接，需 Bridge 运行且实例已链接。",
  "settings.remoteIm.discord.err.tokenFormat": "Bot Token 格式无效。请粘贴 Discord 开发者后台的完整 token（三段，用点分隔）。",
  "settings.remoteIm.discord.intentHint": "请在 Discord 开发者后台开启 Message Content Intent。",
  "settings.remoteIm.qq.riskTitle": "社区桥 — 风险自负",
  "settings.remoteIm.qq.riskHint": "社区 OneBot 桥（NapCat、LLOneBot 等）为第三方能力，可能违反 QQ 服务条款。桥由你自建，账号风险自负。",
  "settings.remoteIm.qq.wsUrlHelp": "来自你自建 OneBot 的正向 WebSocket URL（ws:// 或 wss://）。亦接受 url 别名。不是 HTTP API 基址。",
  "settings.remoteIm.qq.wsUrlPlaceholder": "ws://127.0.0.1:3001",
  "settings.remoteIm.qq.tokenHelp": "可选 OneBot access_token。实例未启用鉴权时留空。遮罩存储，永不写入日志。",
  "settings.remoteIm.qq.tokenPlaceholder": "可选 access_token",
  "settings.remoteIm.qq.allowFromHelp": "允许与机器人对话的 QQ 号，逗号分隔；或 * 表示任意（生产环境建议写明号码）。",
  "settings.remoteIm.qq.guide.title": "QQ OneBot（NapCat）接入",
  "settings.remoteIm.qq.guide.step1": "在本机安装并登录社区 OneBot 宿主（如 NapCat / LLOneBot）— 本应用不内置 QQ 登录。",
  "settings.remoteIm.qq.guide.step2": "启用 OneBot v11 正向 WebSocket，记下 URL（常见为 ws://127.0.0.1:端口/…）。",
  "settings.remoteIm.qq.guide.step3": "若宿主要求 access_token，复制填入；否则 Token 留空。",
  "settings.remoteIm.qq.guide.step4": "将 WS URL 粘贴到此处，设置 allow-from（生产环境避免 *），再点「保存并连接」。Bridge 主动出站 — 无需公网 URL。",
  "settings.remoteIm.qq.guide.softFail": "「测试连接」仅校验是否填写了 ws:// 或 wss:// URL（Token 可选），不会真正打开 WebSocket — 上线需 Bridge 运行且本实例已链接。",
  "settings.remoteIm.qq.err.wsUrlInvalid": "WebSocket URL 无效。请使用 OneBot 正向 WS 的 ws:// 或 wss://主机:端口。",
  "settings.remoteIm.qqbot.intentsTitle": "默认 Intents 含 INTERACTION",
  "settings.remoteIm.qqbot.intentsHint": "Intents 留空时使用产品默认（含 INTERACTION 及相关消息意图）。仅在你清楚机器人所需位掩码或意图名时再覆盖。",
  "settings.remoteIm.qqbot.appIdHelp": "来自 QQ 开放平台（机器人）的 App ID，多为数字。作为非密钥选项保存。",
  "settings.remoteIm.qqbot.appIdPlaceholder": "102012345",
  "settings.remoteIm.qqbot.appSecretHelp": "来自 QQ 开放平台的 App Secret（clientSecret）。遮罩存储，永不写入日志。运行时亦接受 appSecret / client_secret 别名。",
  "settings.remoteIm.qqbot.appSecretPlaceholder": "App Secret",
  "settings.remoteIm.qqbot.intentsHelp": "可选。留空 = 默认含 INTERACTION。高级用户可设置 Bridge 识别的位掩码或意图列表。",
  "settings.remoteIm.qqbot.intentsPlaceholder": "留空使用默认（INTERACTION…）",
  "settings.remoteIm.qqbot.allowFromHelp": "允许与机器人对话的 QQ 用户 ID，逗号分隔；或 * 表示任意（生产环境建议写明 ID）。",
  "settings.remoteIm.qqbot.guide.title": "QQ 官方机器人接入",
  "settings.remoteIm.qqbot.guide.step1": "打开 QQ 开放平台 → 创建 / 选择机器人应用，记下 App ID 与 App Secret。",
  "settings.remoteIm.qqbot.guide.step2": "在开发者后台开启所需能力（私聊 / 群消息、互动等）。",
  "settings.remoteIm.qqbot.guide.step3": "将 App ID 与 App Secret 粘贴到此处。Intents 可留空（默认含 INTERACTION），除非需要自定义掩码。",
  "settings.remoteIm.qqbot.guide.step4": "设置 allow-from（生产环境避免 *），再点「保存并连接」。官方 Gateway 无需公网 URL — 不是 OneBot / NapCat。",
  "settings.remoteIm.qqbot.guide.softFail": "「测试连接」会校验 App ID 格式，并在可联网时尝试换取 access token — 不代表 Gateway 已连接，需 Bridge 运行且本实例已链接。",
  "settings.remoteIm.qqbot.err.appIdFormat": "App ID 格式无效。请粘贴 QQ 开放平台的 AppID（多为数字）。",
