  "settings.remoteIm.weibo.tokenEndpointHelp": "可选 OAuth Token HTTP 端点。留空则使用平台默认。",
  "settings.remoteIm.weibo.tokenEndpointPlaceholder": "https://api.weibo.com/oauth2/access_token",
  "settings.remoteIm.weibo.wsEndpointHelp": "可选私信 WebSocket URL。留空则使用平台默认。无需公网 Webhook。",
