  "settings.remoteIm.weibo.guide.title": "微博接入",
  "settings.remoteIm.weibo.guide.step1": "打开微博开放平台 → 创建（或打开）应用，记录 App Key 与 App Secret。",
  "settings.remoteIm.weibo.guide.step2": "按当前开放平台文档开启私信 / 订阅等机器人所需能力。",
  "settings.remoteIm.weibo.guide.step3": "在此粘贴 App ID 与 App Secret（以粘贴为主）。高级：仅在部署需要非默认主机时覆盖 Token / WebSocket 端点。",
  "settings.remoteIm.weibo.guide.step4": "设置允许用户（优先明确 uid；生产环境避免 *），再点「保存并连接」。WebSocket 无需公网 URL。",
  "settings.remoteIm.weibo.guide.softFail": "「测试连接」仅校验 App ID 格式与凭证是否齐全 — 不代表 WebSocket 已连通，需 Bridge 运行且该实例已链接。",
